from datetime import datetime, timedelta

def is_expired(coupon, now=None):
    now = now or datetime.now
    return now() >= coupon['expires_at']

class FakeClock:
    def __init__(self, start):
        self.current = start

    def __call__(self):
        return self.current

    def advance(self, **kwargs):
        self.current += timedelta(**kwargs)
